mapper.select:
SELECT id, title,`number`, difficulty, submitNum, acceptedNum,timeLimit,memoryLimit from question_base


        AND `number` = #{query.number}


        AND title LIKE CONCAT('%', #{query.title}, '%')



        AND difficulty = #{query.difficulty}



        AND id IN (
        SELECT questionId
        FROM question_tag_related
        WHERE questionTagId IN

            #{tagId}

        GROUP BY questionId
        HAVING COUNT(DISTINCT questionTagId) =#{query.tagIdsSize}
        )


        AND isDelete = 0


ORDER BY id ASC
